def get_cookie_max_age(self, app: "Flask") -> t.Optional[int]:
    """Return the max age in seconds (or None) for the session cookie.
    Uses the ``SESSION_COOKIE_MAX_AGE`` setting.

    The value is validated:

    - ``None`` → ``None``
    - ``int`` (≥ 0) → returned as-is
    - ``datetime.timedelta`` → converted to seconds as ``int``
    - negative int or timedelta → raises ``ValueError``
    - other types (including ``bool``, ``float``, ``str``) → raises ``TypeError``
    """
    val = app.config["SESSION_COOKIE_MAX_AGE"]
    if val is None:
        return None
    if isinstance(val, bool):
        raise TypeError(
            f"SESSION_COOKIE_MAX_AGE must not be a bool, got {type(val).__name__}."
        )
    if isinstance(val, int):
        if val < 0:
            raise ValueError(
                f"SESSION_COOKIE_MAX_AGE must not be negative, got {val}."
            )
        return val
    if isinstance(val, datetime):
        # timedelta is a subclass of numbers.Real but not int/bool
        # Actually datetime is not timedelta, but let's handle timedelta
        raise TypeError(
            f"SESSION_COOKIE_MAX_AGE must be int or timedelta, "
            f"got {type(val).__name__}."
        )
    if isinstance(val, timedelta):
        total = val.total_seconds()
        total_int = int(total)
        if total_int < 0:
            raise ValueError(
                f"SESSION_COOKIE_MAX_AGE must not be negative, "
                f"got {val} ({total_int} seconds)."
            )
        return total_int
    raise TypeError(
        f"SESSION_COOKIE_MAX_AGE must be int or timedelta, "
        f"got {type(val).__name__}."
    )
